#include <iostream>
#include <cstdio>
using namespace std;

#define LL long long
#define mod 1000000009

const int N = 1005;

int C[N][N];
int f[N];

void init() {
    for (int i = 0; i < N; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            if (C[i][j] >= mod) C[i][j] -= mod;
        }
    }

    f[0] = 1;
    for (int i = 1; i < N; ++i)
        f[i] = 1LL * f[i - 1] * i % mod;
}

int n, w, b;

int main() {
    init();
    cin >> n >> w >> b;

    int ans = 0;
    for (int i = 1; i <= w - 1; ++i) {
        ans += 1LL * C[w + b - 3][n - 3] * C[w][i] % mod
             * f[i] % mod * f[b] % mod * f[w - i] % mod;
        if (ans >= mod) ans -= mod;
    }

    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using LL = long long;

const LL mod = 1000000009LL;

LL modPow(LL base, LL exponent) {
    LL result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % mod;
        base = base * base % mod;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, w, b;
    cin >> n >> w >> b;

    int limit = max(w + b, max(w, b));
    vector<LL> factorial(limit + 1, 1);
    vector<LL> inverseFactorial(limit + 1, 1);

    for (int i = 1; i <= limit; ++i)
        factorial[i] = factorial[i - 1] * i % mod;

    inverseFactorial[limit] = modPow(factorial[limit], mod - 2);
    for (int i = limit; i > 0; --i)
        inverseFactorial[i - 1] = inverseFactorial[i] * i % mod;

    auto combination = [&](int total, int chosen) -> LL {
        if (chosen < 0 || chosen > total || total < 0) return 0;
        return factorial[total] * inverseFactorial[chosen] % mod
             * inverseFactorial[total - chosen] % mod;
    };

    LL ans = 0;
    for (int i = 1; i < w; ++i) {
        LL term = combination(w + b - 3, n - 3);
        term = term * combination(w, i) % mod;
        term = term * factorial[i] % mod;
        term = term * factorial[b] % mod;
        term = term * factorial[w - i] % mod;
        ans = (ans + term) % mod;
    }

    cout << ans << '\n';
    return 0;
}

