#include <algorithm>
using namespace std;

using LL = long long;
const int MOD = 1000000009;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, w, b;
    cin >> n >> w >> b;

    int size = max({0, w, b, w + b - 3});
    vector<vector<int>> C(size + 1, vector<int>(size + 1));
    vector<int> f(size + 1);

    for (int i = 0; i <= size; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            if (C[i][j] >= MOD) C[i][j] -= MOD;
        }
    }

    f[0] = 1;
    for (int i = 1; i <= size; ++i)
        f[i] = static_cast<LL>(f[i - 1]) * i % MOD;

    if (w + b - 3 < 0 || n - 3 < 0 || n - 3 > w + b - 3) {
        cout << 0 << '\n';
        return 0;
    }

    int ans = 0;
    for (int i = 1; i < w; ++i) {
        LL term = C[w + b - 3][n - 3];
        term = term * C[w][i] % MOD;
        term = term * f[i] % MOD;
        term = term * f[b] % MOD;
        term = term * f[w - i] % MOD;
        ans = (ans + term) % MOD;
    }

    cout << ans << '\n';
    return 0;
}

